/** Host-local wall-clock interval, using HH:mm and exclusive end (24:00 allowed). */
export type TimeInterval = { start: string; end: string };
/** Repeating host availability; Sunday is 0 and Saturday is 6. */
export type WeeklyAvailability = TimeInterval & { dayOfWeek: number };
/** Replaces weekly availability on a host-local YYYY-MM-DD date; [] blocks the date. */
export type DateOverride = { date: string; intervals: TimeInterval[] };
/** Reserved attendee limits per event type, in host-local calendar periods; total is lifetime. */
export type BookingLimits = {
	perHour?: number;
	perDay?: number;
	perWeek?: number;
	total?: number;
};

/** Event configuration serialized for HTTP and React Query. Duration is real elapsed minutes. */
export type EventType = {
	id: string;
	hostId: string;
	slug: string;
	name: string;
	description: string;
	location: string;
	duration: number;
	capacity: number;
	/** Optional nonnegative price in minor currency units; null/zero means free. */
	price?: number | null;
	/** Three-letter uppercase currency code, supplied together with price. */
	currency?: string | null;
	timezone: string;
	weeklyAvailability: WeeklyAvailability[];
	dateOverrides: DateOverride[];
	limits: BookingLimits;
	active: boolean;
	createdAt: string;
	updatedAt: string;
};

/** Reservation with ISO instants. cancelToken is a private bearer secret; management responses redact it. */
export type Booking = {
	id: string;
	eventTypeId: string;
	hostId: string;
	eventName: string;
	start: string;
	end: string;
	timezone: string;
	name: string;
	email: string;
	status: "confirmed" | "pending_payment" | "cancelled";
	cancelToken: string;
	createdAt: string;
};

/** UTC ISO slot instants and the remaining attendee reservations, including booking limits. */
export type AvailableSlot = { start: string; end: string; remaining: number };
/** External calendar occupancy as absolute instants, with an exclusive end. */
export type BusyInterval = { start: Date; end: Date };
/** Availability for one viewer-local date in the requested IANA timezone. */
export type Availability = {
	slots: AvailableSlot[];
	date: string;
	timezone: string;
};

/** Storage shape: structured configuration is JSON text and timestamps are Date values. */
export type EventTypeRecord = Omit<
	EventType,
	"weeklyAvailability" | "dateOverrides" | "limits" | "createdAt" | "updatedAt"
> & {
	weeklyAvailability: string;
	dateOverrides: string;
	limits: string;
	createdAt: Date;
	updatedAt: Date;
};

/** Storage shape of a reservation, including its private cancellation token. */
export type BookingRecord = Omit<Booking, "start" | "end" | "createdAt"> & {
	start: Date;
	end: Date;
	createdAt: Date;
};

import { z } from "zod";

export const timezoneSchema = z
	.string()
	.min(1)
	.max(100)
	.refine((zone) => {
		try {
			new Intl.DateTimeFormat("en", { timeZone: zone }).format();
			return true;
		} catch {
			return false;
		}
	}, "Invalid timezone");

export const calendarDateSchema = z.iso.date();
const timeSchema = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/);
const endTimeSchema = z.union([timeSchema, z.literal("24:00")]);
const intervalSchema = z
	.object({ start: timeSchema, end: endTimeSchema })
	.refine(
		({ start, end }) => start < end,
		"Availability must end after it starts",
	);
export const weeklyAvailabilitySchema = z
	.object({
		dayOfWeek: z.number().int().min(0).max(6),
		start: timeSchema,
		end: endTimeSchema,
	})
	.refine(
		({ start, end }) => start < end,
		"Availability must end after it starts",
	);
export const dateOverrideSchema = z.object({
	date: calendarDateSchema,
	intervals: z.array(intervalSchema).max(24),
});
const limitSchema = z.number().int().positive().max(1_000_000).optional();
export const bookingLimitsSchema = z.object({
	perHour: limitSchema,
	perDay: limitSchema,
	perWeek: limitSchema,
	total: limitSchema,
});

export const createEventTypeSchema = z
	.object({
		slug: z
			.string()
			.min(1)
			.max(100)
			.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
		name: z.string().trim().min(1).max(200),
		description: z.string().max(5000).default(""),
		location: z.string().max(500).default(""),
		duration: z.number().int().min(1).max(1440),
		capacity: z.number().int().min(1).max(10000).default(1),
		price: z
			.number()
			.int()
			.nonnegative()
			.max(Number.MAX_SAFE_INTEGER)
			.nullish(),
		currency: z
			.string()
			.regex(/^[A-Z]{3}$/)
			.nullish(),
		timezone: timezoneSchema,
		weeklyAvailability: z.array(weeklyAvailabilitySchema).max(168).default([]),
		dateOverrides: z
			.array(dateOverrideSchema)
			.max(366)
			.default([])
			.refine(
				(overrides) =>
					new Set(overrides.map((override) => override.date)).size ===
					overrides.length,
				"Only one override is allowed per date",
			),
		limits: bookingLimitsSchema.default({}),
		active: z.boolean().default(true),
	})
	.refine(({ price, currency }) => (price != null) === (currency != null), {
		message: "Supply price and currency together",
		path: ["currency"],
	});

export const createBookingSchema = z.object({
	start: z.iso.datetime({ offset: true }),
	timezone: timezoneSchema,
	name: z.string().trim().min(1).max(200),
	email: z
		.email()
		.max(320)
		.transform((value) => value.toLowerCase()),
});
export const availabilityQuerySchema = z.object({
	date: calendarDateSchema,
	timezone: timezoneSchema,
});
export const rescheduleBookingSchema = z.object({
	start: z.iso.datetime({ offset: true }),
	timezone: timezoneSchema,
});
export const listBookingsQuerySchema = z.object({
	period: z.enum(["upcoming", "past", "all"]).default("upcoming"),
	eventTypeId: z.string().min(1).optional(),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const eventFacts = { eventTypeId: z.string(), hostId: z.string() };
const hostFacts = { hostId: z.string().optional() };
const bookingFacts = { bookingId: z.string(), hostId: z.string() };

export const calendarPermissions = definePermissions("calendar", {
	eventType: {
		list: permission(z.object(hostFacts)),
		read: permission(z.object({ ...eventFacts, public: z.boolean() })),
		create: permission(z.object(hostFacts)),
		update: permission(z.object(eventFacts)),
		delete: permission(z.object(eventFacts)),
	},
	availability: { read: permission(z.object(eventFacts)) },
	booking: {
		list: permission(z.object(hostFacts)),
		create: permission(z.object(eventFacts)),
		read: permission(z.object({ ...bookingFacts, tokenValid: z.boolean() })),
		cancel: permission(z.object({ ...bookingFacts, tokenValid: z.boolean() })),
		reschedule: permission(
			z.object({ ...bookingFacts, tokenValid: z.boolean() }),
		),
		confirmPayment: permission(z.object(bookingFacts)),
		remind: permission(z.object(bookingFacts)),
	},
});

"use client";

import { Button } from "@/components/ui/button";
import { generateBookingInvite } from "@btst/plugin-calendar/client/hooks";
import type { Booking } from "../../types";

export function CalendarInviteDownload({
	booking,
}: {
	booking: Omit<Booking, "cancelToken">;
}) {
	return (
		<Button className="min-h-11" variant="outline" asChild>
			<a
				download="booking.ics"
				href={`data:text/calendar;charset=utf-8,${encodeURIComponent(generateBookingInvite(booking))}`}
			>
				Download calendar invite (.ics)
			</a>
		</Button>
	);
}

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { calendarPermissions } from "../../permissions";
import { CalendarError, CalendarLoading, CalendarNotFound } from "./shared";

const Dashboard = lazy(() =>
	import("./pages/dashboard").then((m) => ({
		default: m.CalendarDashboardPage,
	})),
);
const Editor = lazy(() =>
	import("./pages/event-editor").then((m) => ({
		default: m.CalendarEventEditorPage,
	})),
);
const Booking = lazy(() =>
	import("./pages/booking").then((m) => ({ default: m.CalendarBookingPage })),
);
const Cancellation = lazy(() =>
	import("./pages/cancellation").then((m) => ({
		default: m.CalendarCancellationPage,
	})),
);
const Reschedule = lazy(() =>
	import("./pages/reschedule").then((m) => ({
		default: m.CalendarReschedulePage,
	})),
);

const boundary = {
	ErrorComponent: CalendarError,
	LoadingComponent: CalendarLoading,
	NotFoundComponent: CalendarNotFound,
	onError: (error: Error) => console.error("[btst/calendar]", error),
};

export function CalendarDashboardPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/calendar"
			permission={calendarPermissions.eventType.list({})}
			PageComponent={Dashboard}
		/>
	);
}

export function CalendarEventEditorPageComponent({ id }: { id?: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={id ? `/calendar/events/${id}/edit` : "/calendar/events/new"}
			permission={id ? undefined : calendarPermissions.eventType.create({})}
			PageComponent={Editor}
			props={{ id }}
		/>
	);
}

export function CalendarBookingPageComponent({ slug }: { slug: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/book/${slug}`}
			PageComponent={Booking}
			props={{ slug }}
		/>
	);
}

export function CalendarCancellationPageComponent({
	token,
}: {
	token: string;
}) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/cancel/${token}`}
			PageComponent={Cancellation}
			props={{ token }}
		/>
	);
}

export function CalendarReschedulePageComponent({ token }: { token: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/reschedule/${token}`}
			PageComponent={Reschedule}
			props={{ token }}
		/>
	);
}

"use client";

import { useEffect, useState, type FormEvent } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { Booking } from "../../../types";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import {
	useCalendarSlots,
	useCreateCalendarBooking,
	usePublicCalendarEvent,
} from "@btst/plugin-calendar/client/hooks";
import {
	CalendarPage,
	Field,
	formatCalendarTime,
	formatCalendarPrice,
} from "../shared";
import { CalendarInviteDownload } from "../invite-download";
import { CalendarTimePicker, calendarToday } from "../time-picker";

export function CalendarBookingPage({ slug }: { slug: string }) {
	const { data: event } = usePublicCalendarEvent(slug);
	const [timezone, setTimezone] = useState(event.timezone);
	const [date, setDate] = useState(() => calendarToday(event.timezone));
	const [start, setStart] = useState("");
	const [confirmation, setConfirmation] = useState<Booking>();
	const slots = useCalendarSlots(slug, date, timezone);
	const create = useCreateCalendarBooking();
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	useEffect(() => {
		const localZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
		setTimezone(localZone);
		setDate(calendarToday(localZone));
	}, []);
	const chosenSlot = slots.data?.slots.find((slot) => slot.start === start);
	const submit = async (e: FormEvent<HTMLFormElement>) => {
		e.preventDefault();
		if (!chosenSlot) return;
		const data = new FormData(e.currentTarget);
		try {
			const booking = await create.mutateAsync({
				slug,
				start,
				timezone,
				name: String(data.get("name")),
				email: String(data.get("email")),
			});
			setConfirmation(booking);
		} catch {
			// The mutation exposes its error beside the booking form.
		}
	};
	if (confirmation)
		return (
			<CalendarPage>
				<section aria-live="polite" className="max-w-xl space-y-4">
					<h1 className="text-2xl font-semibold sm:text-3xl">
						{confirmation.status === "pending_payment"
							? "Booking awaiting payment"
							: "Booking confirmed"}
					</h1>
					{confirmation.status === "pending_payment" && (
						<p>
							Your time is held while payment is pending. Contact the host to
							complete payment.
						</p>
					)}
					<p>{confirmation.eventName}</p>
					<p>
						{formatCalendarTime(confirmation.start, confirmation.timezone)} (
						{confirmation.timezone})
					</p>
					{event.location && (
						<p className="break-words">Location: {event.location}</p>
					)}
					<p>Save this link to manage your booking.</p>
					<CalendarInviteDownload booking={confirmation} />
					<Button className="min-h-11" variant="outline" asChild>
						<Link
							href={
								resolve("calendar", "cancel", confirmation.cancelToken).href
							}
						>
							Manage or cancel booking
						</Link>
					</Button>
				</section>
			</CalendarPage>
		);
	return (
		<CalendarPage>
			<header className="max-w-2xl space-y-2">
				<h1 className="break-words text-2xl font-semibold sm:text-3xl">
					{event.name}
				</h1>
				<p className="text-muted-foreground">
					{event.duration} minutes ·{" "}
					{event.capacity === 1
						? "1:1 booking"
						: `Up to ${event.capacity} attendees`}
				</p>
				{event.description && (
					<p className="whitespace-pre-wrap break-words">{event.description}</p>
				)}
				{event.location && (
					<p className="break-words">Location: {event.location}</p>
				)}
				{(event.price ?? 0) > 0 && event.currency && (
					<p>
						Price: {formatCalendarPrice(event.price!, event.currency)}. Payment
						is required to confirm your booking.
					</p>
				)}
			</header>
			<div className="grid min-w-0 gap-8 lg:grid-cols-2">
				<CalendarTimePicker
					date={date}
					timezone={timezone}
					start={start}
					onDate={setDate}
					onTimezone={setTimezone}
					onStart={setStart}
					slots={slots}
					capacity={event.capacity}
				/>
				<form
					onSubmit={submit}
					className="min-w-0 space-y-5 rounded-lg border p-4 sm:p-6"
				>
					<h2 className="text-xl font-semibold">Your details</h2>
					{chosenSlot ? (
						<p className="text-sm">
							{formatCalendarTime(chosenSlot.start, timezone)} ({timezone})
						</p>
					) : (
						<p className="text-sm text-muted-foreground">
							Select an available time to confirm your booking.
						</p>
					)}
					<Field id="calendar-name" label="Your name">
						<Input
							id="calendar-name"
							className="min-h-11"
							name="name"
							autoComplete="name"
							required
							maxLength={200}
						/>
					</Field>
					<Field id="calendar-email" label="Email">
						<Input
							id="calendar-email"
							className="min-h-11"
							name="email"
							type="email"
							autoComplete="email"
							required
							maxLength={320}
						/>
					</Field>
					{create.error && (
						<p role="alert" className="text-destructive">
							{create.error.message}
						</p>
					)}
					<Button
						className="min-h-11 w-full"
						type="submit"
						disabled={!chosenSlot || create.isPending || slots.isFetching}
					>
						{create.isPending
							? "Reserving booking…"
							: (event.price ?? 0) > 0
								? "Reserve pending payment"
								: "Confirm booking"}
					</Button>
				</form>
			</div>
		</CalendarPage>
	);
}

"use client";

import { Button } from "@/components/ui/button";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import { CalendarInviteDownload } from "../invite-download";
import { useCalendarBooking, useCancelCalendarBooking } from "@btst/plugin-calendar/client/hooks";
import { CalendarPage, formatCalendarTime } from "../shared";

export function CalendarCancellationPage({ token }: { token: string }) {
	const { data } = useCalendarBooking(token);
	const cancel = useCancelCalendarBooking();
	const booking = cancel.data ?? data;
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	return (
		<CalendarPage>
			<section className="max-w-xl space-y-5" aria-live="polite">
				<h1 className="text-2xl font-semibold sm:text-3xl">
					{booking.status === "cancelled"
						? "Booking cancelled"
						: "Manage booking"}
				</h1>
				<h2 className="break-words text-xl">{booking.eventName}</h2>
				<p>
					{formatCalendarTime(booking.start, booking.timezone)} (
					{booking.timezone})
				</p>
				{booking.status === "pending_payment" && (
					<p>
						Payment pending. Your time is held until the host confirms payment
						or the booking is cancelled.
					</p>
				)}
				<CalendarInviteDownload booking={booking} />
				{booking.status === "cancelled" ? (
					<p>Your booking has been cancelled.</p>
				) : (
					<>
						{Date.parse(booking.start) > Date.now() && (
							<Button className="min-h-11" variant="outline" asChild>
								<Link href={resolve("calendar", "reschedule", token).href}>
									Reschedule booking
								</Link>
							</Button>
						)}
						<p>Cancel this booking if you can no longer attend.</p>
						{cancel.error && (
							<p role="alert" className="text-destructive">
								{cancel.error.message}
							</p>
						)}
						<Button
							className="min-h-11"
							variant="destructive"
							disabled={cancel.isPending}
							onClick={() => cancel.mutate(token)}
						>
							{cancel.isPending ? "Cancelling booking…" : "Cancel booking"}
						</Button>
					</>
				)}
			</section>
		</CalendarPage>
	);
}

"use client";

import { useState } from "react";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { calendarPermissions } from "../../../permissions";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import {
	useCalendarBookings,
	useCalendarEvents,
	useCancelHostCalendarBooking,
	useDeleteCalendarEvent,
} from "@btst/plugin-calendar/client/hooks";
import { CalendarPage, formatCalendarTime } from "../shared";
import { CalendarInviteDownload } from "../invite-download";

export function CalendarDashboardPage() {
	const { data: events } = useCalendarEvents();
	const remove = useDeleteCalendarEvent();
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	useRegisterPageAIContext({
		routeName: "calendar-admin",
		pageDescription: JSON.stringify({
			page: "Read-only Calendar dashboard summary. No mutation tools are available.",
			eventTypes: events.length,
			acceptingBookings: events.filter((event) => event.active).length,
		}),
	});
	return (
		<CalendarPage>
			<header className="flex flex-wrap items-center justify-between gap-4">
				<div>
					<h1 className="text-2xl font-semibold sm:text-3xl">Calendar</h1>
					<p className="mt-1 text-muted-foreground">
						Manage event types and scheduled bookings.
					</p>
				</div>
				<PermissionAccess permission={calendarPermissions.eventType.create({})}>
					<Button className="min-h-11" asChild>
						<Link href={resolve("calendar", "events", "new").href}>
							New event type
						</Link>
					</Button>
				</PermissionAccess>
			</header>
			<section aria-labelledby="calendar-events-heading" className="space-y-4">
				<h2 id="calendar-events-heading" className="text-xl font-semibold">
					Event types
				</h2>
				{remove.error && (
					<p role="alert" className="text-destructive">
						{remove.error.message}
					</p>
				)}
				{events.length === 0 ? (
					<p className="rounded-lg border p-6 text-muted-foreground">
						No event types yet. Create one to set your availability and share a
						booking page.
					</p>
				) : (
					<ul className="divide-y rounded-lg border">
						{events.map((event) => (
							<li
								key={event.id}
								className="flex min-w-0 flex-wrap items-center justify-between gap-4 p-4 sm:p-5"
							>
								<div className="min-w-0">
									<h3 className="break-words font-medium">{event.name}</h3>
									<p className="text-sm text-muted-foreground">
										{event.duration} minutes ·{" "}
										{event.capacity === 1
											? "1:1"
											: `Up to ${event.capacity} attendees`}{" "}
										· {event.active ? "Accepting bookings" : "Paused"}
									</p>
								</div>
								<div className="flex flex-wrap gap-2">
									{event.active && (
										<Button className="min-h-11" variant="outline" asChild>
											<Link href={resolve("calendar", "book", event.slug).href}>
												Booking page
											</Link>
										</Button>
									)}
									<PermissionAccess
										permission={calendarPermissions.eventType.update({
											eventTypeId: event.id,
											hostId: event.hostId,
										})}
									>
										<Button className="min-h-11" variant="outline" asChild>
											<Link
												href={
													resolve("calendar", "events", event.id, "edit").href
												}
											>
												Edit<span className="sr-only"> {event.name}</span>
											</Link>
										</Button>
									</PermissionAccess>
									<PermissionAccess
										permission={calendarPermissions.eventType.delete({
											eventTypeId: event.id,
											hostId: event.hostId,
										})}
									>
										<Button
											className="min-h-11"
											variant="ghost"
											disabled={remove.isPending}
											onClick={() => {
												if (
													window.confirm(
														`Delete ${event.name}? Existing bookings must be cancelled first.`,
													)
												)
													remove.mutate(event.id);
											}}
										>
											Delete<span className="sr-only"> {event.name}</span>
										</Button>
									</PermissionAccess>
								</div>
							</li>
						))}
					</ul>
				)}
			</section>
			<PermissionAccess permission={calendarPermissions.booking.list({})}>
				<BookingsSection />
			</PermissionAccess>
		</CalendarPage>
	);
}

function BookingsSection() {
	const [period, setPeriod] = useState<"upcoming" | "past">("upcoming");
	const { data: bookings } = useCalendarBookings(period);
	const cancel = useCancelHostCalendarBooking();
	return (
		<section aria-labelledby="calendar-bookings-heading" className="space-y-4">
			<div className="flex flex-wrap items-center justify-between gap-3">
				<h2 id="calendar-bookings-heading" className="text-xl font-semibold">
					Bookings
				</h2>
				<div className="flex gap-2" aria-label="Booking period">
					{(["upcoming", "past"] as const).map((value) => (
						<Button
							key={value}
							className="min-h-11"
							variant={period === value ? "default" : "outline"}
							aria-pressed={period === value}
							onClick={() => setPeriod(value)}
						>
							{value === "upcoming" ? "Upcoming" : "Past"}
						</Button>
					))}
				</div>
			</div>
			{cancel.error && (
				<p role="alert" className="text-destructive">
					{cancel.error.message}
				</p>
			)}
			{bookings.length === 0 ? (
				<p className="rounded-lg border p-6 text-muted-foreground">
					No {period} bookings.
				</p>
			) : (
				<ul className="divide-y rounded-lg border">
					{bookings.map((booking) => (
						<li key={booking.id} className="space-y-1 p-4 sm:p-5">
							<div className="flex flex-wrap items-baseline justify-between gap-2">
								<h3 className="break-words font-medium">{booking.eventName}</h3>
								<span className="text-sm">
									{booking.status === "cancelled"
										? "Cancelled"
										: booking.status === "pending_payment"
											? "Payment pending"
											: "Confirmed"}
								</span>
							</div>
							<p>
								{formatCalendarTime(booking.start, booking.timezone)} (
								{booking.timezone})
							</p>
							<p className="break-words text-sm text-muted-foreground">
								{booking.name} · {booking.email}
							</p>
							<CalendarInviteDownload booking={booking} />
							{booking.status !== "cancelled" && (
								<PermissionAccess
									permission={calendarPermissions.booking.cancel({
										bookingId: booking.id,
										hostId: booking.hostId,
										tokenValid: false,
									})}
								>
									<Button
										className="min-h-11"
										variant="outline"
										disabled={cancel.isPending}
										onClick={() => cancel.mutate(booking.id)}
									>
										Cancel booking
										<span className="sr-only"> for {booking.name}</span>
									</Button>
								</PermissionAccess>
							)}
						</li>
					))}
				</ul>
			)}
		</section>
	);
}

"use client";

import { useId, useState, type FormEvent } from "react";
