const days = [
	"Sunday",
	"Monday",
	"Tuesday",
	"Wednesday",
	"Thursday",
	"Friday",
	"Saturday",
];
const emptyEvent: CalendarEventInput = {
	name: "",
	slug: "",
	description: "",
	location: "",
	duration: 30,
	capacity: 1,
	timezone: "UTC",
	active: true,
	limits: {},
	dateOverrides: [],
