}

function ExistingEventEditor({ id }: { id: string }) {
	const { data: event } = useCalendarEvent(id);
	return (
		<PermissionRouteAccess
			permission={calendarPermissions.eventType.update({
				eventTypeId: id,
				hostId: event.hostId,
			})}
			LoadingComponent={CalendarLoading}
		>
			<EventForm
				key={id}
				id={id}
