export const calendarSelectClass =
	"border-input bg-background min-h-11 w-full min-w-0 rounded-md border px-3 text-sm focus-visible:outline-2 focus-visible:outline-ring";

export function formatCalendarTime(value: string, timezone: string) {
	return new Intl.DateTimeFormat(undefined, {
		dateStyle: "medium",
		timeStyle: "short",
		timeZone: timezone,
	}).format(new Date(value));
}

export function formatCalendarPrice(price: number, currency: string) {
	const formatter = new Intl.NumberFormat(undefined, {
		style: "currency",
		currency,
	});
	return formatter.format(
		price / 10 ** (formatter.resolvedOptions().maximumFractionDigits ?? 2),
	);
}

"use client";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { useCalendarSlots } from "@btst/plugin-calendar/client/hooks";
import { Field, calendarSelectClass } from "./shared";

export function calendarToday(timezone: string) {
	return new Intl.DateTimeFormat("en-CA", {
		timeZone: timezone,
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).format(new Date());
}

export function CalendarTimePicker({
	date,
	timezone,
	start,
	onDate,
	onTimezone,
	onStart,
	slots,
	capacity = 1,
}: {
	date: string;
	timezone: string;
	start: string;
	onDate: (date: string) => void;
	onTimezone: (timezone: string) => void;
	onStart: (start: string) => void;
	slots: ReturnType<typeof useCalendarSlots>;
	capacity?: number;
}) {
	const zones = Array.from(
		new Set([timezone, "UTC", ...Intl.supportedValuesOf("timeZone")]),
	);
	return (
		<section
			aria-labelledby="calendar-choose-time"
			className="min-w-0 space-y-5"
		>
			<h2 id="calendar-choose-time" className="text-xl font-semibold">
				Choose a time
			</h2>
			<div className="grid min-w-0 gap-4 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2">
				<Field id="calendar-date" label="Date">
					<Input
						id="calendar-date"
						className="min-h-11"
						type="date"
						required
						min={calendarToday(timezone)}
						value={date}
						onChange={(e) => {
							if (e.target.value) {
								onDate(e.target.value);
								onStart("");
							}
						}}
					/>
				</Field>
				<Field id="calendar-timezone" label="Timezone">
					<select
						id="calendar-timezone"
						className={calendarSelectClass}
						value={timezone}
						onChange={(e) => {
							onTimezone(e.target.value);
							onStart("");
						}}
					>
						{zones.map((zone) => (
							<option key={zone} value={zone}>
								{zone}
							</option>
						))}
					</select>
				</Field>
			</div>
			{slots.isPending || slots.isFetching ? (
				<p role="status">Loading available times…</p>
			) : slots.error ? (
				<div role="alert" className="space-y-3">
					<p>{slots.error.message}</p>
					<Button
						className="min-h-11"
						variant="outline"
						onClick={() => void slots.refetch()}
					>
						Retry available times
					</Button>
				</div>
			) : slots.data?.slots.length === 0 ? (
				<p className="rounded-lg border p-5 text-muted-foreground">
					No available times on this date. Choose another date.
				</p>
			) : (
				<div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
					{slots.data?.slots.map((slot) => (
						<Button
							key={slot.start}
							data-testid="calendar-slot"
							className="h-auto min-h-11 min-w-0 flex-col whitespace-normal px-2 py-2"
							variant={start === slot.start ? "default" : "outline"}
							aria-pressed={start === slot.start}
							onClick={() => onStart(slot.start)}
						>
							{new Intl.DateTimeFormat(undefined, {
								hour: "numeric",
								minute: "2-digit",
								timeZoneName: "short",
								timeZone: timezone,
							}).format(new Date(slot.start))}
							{capacity > 1 && (
								<span className="text-xs">({slot.remaining} left)</span>
							)}
						</Button>
					))}
				</div>
			)}
		</section>
	);
}
